def install_app_dependencies(self, app: BaseConfig):
    """
    Install the dependencies for the app.

    :param app: The config object for the app
    """
    if app.requires:
        # Clean up any existing app packages to remove old dependencies
        app_packages_path = self.app_packages_path(app)
        if app_packages_path.exists():
            self.shutil.rmtree(app_packages_path)
        app_packages_path.mkdir(parents=True, exist_ok=True)

        try:
            self.subprocess.run(
                [
                    sys.executable, "-m",
                    "pip", "install",
                    "--upgrade",
                    "--no-user",
                    "--target={}".format(app_packages_path),
                ] + app.requires,
                check=True,
            )
